source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 3]
    for r, c in points:
        # A five-cell-wide emblem centered on each marker.
        for dc in range(-2, 3):
            if 0 <= r - 2 < h and 0 <= c + dc < w:
                out[r - 2][c + dc] = 5
            if 0 <= r + 2 < h and 0 <= c + dc < w:
                out[r + 2][c + dc] = 8
        for rr in (r - 1, r, r + 1):
            for cc in (c - 2, c + 2):
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 2
        if 0 <= r - 1 < h and 0 <= c < w:
            out[r - 1][c] = 5
        if 0 <= r + 2 < h:
            for cc in range(w):
                # The horizontal line runs across the canvas; emblem cells are 8.
                if not (c - 2 <= cc <= c + 2):
                    out[r + 2][cc] = 2
    return out
'''
